package com.ruoyi.kangaroo.ext.governance;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.kangaroo.ext.KgJdbc.p;
import static com.ruoyi.kangaroo.ext.governance.KgGovernanceExecutionTest.*;
import java.util.*;
import org.junit.jupiter.api.*;
import com.ruoyi.common.exception.ServiceException;

class KgMerchantCompletionExecutionTest {
    @Test void cannotCancelMerchantCaseAfterLinkedUserPenaltyWasExecuted(){
        long id=h.create("collusion");db.update("update kg_member_case set status='executed'",p());
        assertThrows(ServiceException.class,()->run(()->KgMerchantSanctionsExecutionTest.service.decide(id,p("execute",false,"note","复核发现需要进一步核查原始证据。"),"admin:a")));
        assertEquals("notified",db.one("select status from kg_merchant_case where case_id=:c",p("c",id)).get("status"));
    }
    KgMerchantSanctionsExecutionTest h=new KgMerchantSanctionsExecutionTest();
    @BeforeAll static void init(){KgMerchantSanctionsExecutionTest.init();}
    @BeforeEach void reset(){h.reset();}
    KgMerchantSettlement finance(){return KgMerchantSanctionsExecutionTest.settlement;}
    long draft(String month,long gross){return in(()->finance().save(p("storeId",2,"month",month,"grossFen",gross,"basis","按合同及当月已完成订单核对服务费分成。","version",0),"admin:maker"));}
    Map<String,Object> command(long ver){return p("version",ver,"note","已核对合同、账期与对账凭证。");}
    @Test void centsRoundHalfUpAndDoNotCompound(){long id=draft("2020-01",10001);run(()->finance().applyPenalty(2L,"2020-01",123L,"admin:a"));run(()->finance().applyPenalty(2L,"2020-01",124L,"admin:a"));Map<String,Object> f=finance().detail(id);assertEquals(5001L,((Number)f.get("deductionFen")).longValue());assertEquals(5000L,((Number)f.get("netFen")).longValue());}
    @Test void financialStatesVersionMakerCheckAndProof(){long id=draft("2020-01",10001);run(()->finance().applyPenalty(2L,"2020-01",123L,"admin:a"));assertThrows(ServiceException.class,()->run(()->finance().command(id,"approve",command(2),"admin:maker")));assertThrows(ServiceException.class,()->run(()->finance().command(id,"approve",command(1),"admin:checker")));run(()->finance().command(id,"approve",command(2),"admin:checker"));Map<String,Object>b=command(3);b.put("proof","银行凭证 TEST-0001");b.put("paidFen",10001);assertThrows(ServiceException.class,()->run(()->finance().command(id,"paid",b,"admin:cashier")));b.put("paidFen",5000);run(()->finance().command(id,"paid",b,"admin:cashier"));assertEquals("paid",finance().detail(id).get("status"));assertThrows(ServiceException.class,()->run(()->finance().command(id,"paid",b,"admin:cashier")));assertThrows(ServiceException.class,()->run(()->finance().applyPenalty(2L,"2020-01",125L,"admin:a")));assertEquals(5000L,((Number)finance().detail(id).get("netFen")).longValue());}
    @Test void openMonthAndUnresolvedSanctionCannotPay(){long current=draft(Governance.now().toString().substring(0,7),20000);assertThrows(ServiceException.class,()->run(()->finance().command(current,"approve",command(1),"admin:checker")));long old=draft("2020-01",20000);h.create("positive_fraud");assertThrows(ServiceException.class,()->run(()->finance().command(old,"approve",command(1),"admin:checker")));}
    @Test void decisionWithdrawsOnlyEvidenceAndCreatesUnpricedLedger(){long id=h.create("positive_fraud");h.elapsed(id);h.execute(id);Map<String,Object> d=KgMerchantSanctionsExecutionTest.service.detail(2L,id,false);assertFalse(d.containsKey("relatedReviews"));Map<?,?> f=(Map<?,?>)d.get("settlement");assertNull(f.get("grossFen"));assertEquals("draft",f.get("status"));assertEquals("1",db.one("select revoked from kg_member_review_check where review_id=:r",p("r",KgMerchantSanctionsExecutionTest.review)).get("revoked"));assertEquals("1",db.one("select status from kg_review where review_id=:r",p("r",KgMerchantSanctionsExecutionTest.review)).get("status"));assertEquals("0",db.one("select status from kg_app_user where user_id=1",p()).get("status"));}
    @Test void collusionWaitsForBothAppealsAndThenFreezesMember(){long id=h.create("collusion");h.elapsed(id);Map<String,Object>b=p("execute",true,"relatedReviewed",true,"note","已核对商家及用户申诉和原始证据，确认联动处理。");assertThrows(ServiceException.class,()->run(()->KgMerchantSanctionsExecutionTest.service.decide(id,b,"admin:a")));assertEquals("0",h.status());assertEquals(0,db.count("select count(*) from kg_merchant_settlement",p()));db.update("update kg_member_case set appeal_deadline=date_sub(now(),interval 1 day)",p());run(()->KgMerchantSanctionsExecutionTest.service.decide(id,b,"admin:a"));assertEquals("1",h.status());assertEquals("1",db.one("select frozen from kg_member_restriction where app_user_id=1",p()).get("frozen"));assertEquals("1",db.one("select status from kg_app_user where user_id=1",p()).get("status"));assertEquals(1,db.count("select count(*) from kg_member_case where status='executed'",p()));}
    @Test void missingOrUnrelatedEvidenceRollsBackNotice(){assertThrows(ServiceException.class,()->in(()->KgMerchantSanctionsExecutionTest.service.create(p("storeId",2,"requestKey","invalid_evidence_01","violation","positive_fraud","facts","已核对涉及门店的原始评价与事实。","basis","原始材料和评价存在但不能跨店操作。","reviewIds",Arrays.asList(999999)),"admin:a")));assertEquals(0,db.count("select count(*) from kg_merchant_case",p()));}
    @Test void manualSettlementRollbackAndReturn(){long id=draft("2020-01",100);run(()->finance().command(id,"approve",command(1),"admin:b"));run(()->finance().command(id,"return",command(2),"admin:b"));assertEquals("draft",finance().detail(id).get("status"));assertThrows(ServiceException.class,()->run(()->finance().save(p("storeId",2,"month","2020-01","grossFen",100,"basis","实际分成对账金额说明完整。","version",1),"admin:maker")));}
    @Test void invalidMoneyRejected(){for(Object bad:Arrays.asList("1.5","NaN","-1","100000000001"))assertThrows(ServiceException.class,()->KgMerchantSettlement.money(bad));}
    @Test void financeAndDeliveryRequireIndependentPermissions()throws Exception{Class<?> c=com.ruoyi.kangaroo.controller.admin.KgGovernanceController.class;for(String name:Arrays.asList("settlements","settlement","saveSettlement","settlementCommand","deliveries")){java.lang.reflect.Method m=Arrays.stream(c.getMethods()).filter(x->name.equals(x.getName())).findFirst().get();String guard=m.getAnnotation(org.springframework.security.access.prepost.PreAuthorize.class).value();assertTrue(guard.contains(name.equals("deliveries")?"kangaroo:delivery:query":"kangaroo:merchantfinance:"));}}
}
